class Solution {
    public void solveSudoku(char[][] board) {
        solve(board);
    }

    private boolean solve(char[][] board) {
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] != '.') continue;
                for (char c = '1'; c <= '9'; c++) {
                    if (isValid(board, i, j, c)) {
                        board[i][j] = c;
                        if (solve(board)) return true;
                        board[i][j] = '.';
                    }
                }
                return false;
            }
        }
        return true;
    }

    private boolean isValid(char[][] board, int row, int col, char c) {
        int boxRow = 3 * (row / 3), boxCol = 3 * (col / 3);
        for (int i = 0; i < 9; i++) {
            if (board[row][i] == c) return false;
            if (board[i][col] == c) return false;
            if (board[boxRow + i / 3][boxCol + i % 3] == c) return false;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public void solveSudoku(char[][] board) {
        boolean[][] rows = new boolean[9][10];
        boolean[][] cols = new boolean[9][10];
        boolean[][] boxes = new boolean[9][10];
        List<int[]> emptyCells = new ArrayList<>();
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') {
                    emptyCells.add(new int[]{i, j});
                } else {
                    int num = board[i][j] - '0';
                    rows[i][num] = true;
                    cols[j][num] = true;
                    boxes[(i / 3) * 3 + j / 3][num] = true;
                }
            }
        }
        solve(board, emptyCells, 0, rows, cols, boxes);
    }

    private boolean solve(char[][] board, List<int[]> emptyCells, int idx, boolean[][] rows, boolean[][] cols, boolean[][] boxes) {
        if (idx == emptyCells.size()) return true;
        int r = emptyCells.get(idx)[0];
        int c = emptyCells.get(idx)[1];
        int box = (r / 3) * 3 + c / 3;
        for (int num = 1; num <= 9; num++) {
            if (!rows[r][num] && !cols[c][num] && !boxes[box][num]) {
                board[r][c] = (char) ('0' + num);
                rows[r][num] = true;
                cols[c][num] = true;
                boxes[box][num] = true;
                if (solve(board, emptyCells, idx + 1, rows, cols, boxes)) return true;
                board[r][c] = '.';
                rows[r][num] = false;
                cols[c][num] = false;
                boxes[box][num] = false;
            }
        }
        return false;
    }
}
